/* Alongside ALS service worker — generated by build.py from _sw.js. Do not edit sw.js directly.
   Strategy: pages and data are network-first (fresh when online, cached when not);
   hashed assets, icons and images are cache-first. Nothing is cached for /api/. */
const VERSION = "2552d4b2";
const SHELL = "aa-shell-" + VERSION;      // pages + versioned assets, replaced on every deploy
const DATA = "aa-data";                   // JSON directories, refreshed in place
const MEDIA = "aa-media";                 // images, icons, PDF script, ZIP tables
const PRECACHE = ["/", "/about", "/app", "/appointment", "/data/summary.json", "/favicon.svg", "/get-ready", "/grants", "/icons/apple-touch-icon.png", "/icons/icon-192.png", "/manifest.webmanifest", "/map.js?v=109ead05", "/my-plan", "/offline", "/resources", "/road-ahead", "/services", "/site.css?v=3cc0801e", "/site.js?v=aada9b9b", "/understanding-als"];
const OFFLINE = "/offline";
const NETWORK_TIMEOUT = 4000;

self.addEventListener("install", (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(SHELL);
    // Add one by one so a single failure doesn't abort the install.
    await Promise.all(PRECACHE.map(u => c.add(new Request(u, { cache: "reload" })).catch(() => {})));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (e) => {
  e.waitUntil((async () => {
    const keep = new Set([SHELL, DATA, MEDIA]);
    for (const k of await caches.keys()) if (!keep.has(k)) await caches.delete(k);
    if (self.registration.navigationPreload) { try { await self.registration.navigationPreload.enable(); } catch {} }
    await self.clients.claim();
  })());
});

self.addEventListener("message", (e) => { if (e.data === "skipWaiting") self.skipWaiting(); });

const pageKey = (url) => { const u = new URL(url); u.search = ""; u.hash = ""; return u.pathname.replace(/\.html$/, "").replace(/\/$/, "") || "/"; };
const timeout = (ms) => new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), ms));

async function networkFirst(req, cacheName, { key, preload } = {}) {
  const c = await caches.open(cacheName);
  try {
    const res = await Promise.race([preload ? preload.then(r => r || fetch(req)) : fetch(req), timeout(NETWORK_TIMEOUT)]);
    if (res && res.ok) c.put(key || req, res.clone());
    if (res) return res;
  } catch {}
  const hit = await c.match(key || req, { ignoreSearch: !!key });
  if (hit) return hit;
  throw new Error("offline");
}
async function cacheFirst(req, cacheName) {
  const c = await caches.open(cacheName);
  const hit = await c.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok) c.put(req, res.clone());
  return res;
}

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;              // fonts, Turnstile, external links: browser default
  if (url.pathname.startsWith("/api/")) return;

  if (req.mode === "navigate") {
    e.respondWith((async () => {
      try { return await networkFirst(req, SHELL, { key: pageKey(req.url), preload: e.preloadResponse }); }
      catch { return (await caches.match(OFFLINE)) || new Response("You're offline.", { status: 503, headers: { "Content-Type": "text/plain" } }); }
    })());
    return;
  }
  if (url.pathname.startsWith("/data/")) {
    e.respondWith(networkFirst(req, DATA).catch(() => new Response("{}", { status: 503, headers: { "Content-Type": "application/json" } })));
    return;
  }
  if (/\.(css|js)$/.test(url.pathname) && url.searchParams.has("v")) { e.respondWith(cacheFirst(req, SHELL)); return; }
  if (url.pathname.startsWith("/icons/") || url.pathname.startsWith("/assets/") || url.pathname === "/favicon.svg" || url.pathname === "/tracker-pdf.js" || url.pathname === "/manifest.webmanifest") {
    e.respondWith(cacheFirst(req, MEDIA)); return;
  }
});
